#requires -Version 5.1
[CmdletBinding()]param([string[]]$Names=@('microsoft.com','github.com'),[string]$DomainName)
$root='C:\ProgramData\BlueRidge\DNSReports';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "dns-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'dns-client-diagnostics.log') -Append|Out-Null
try{Get-DnsClientServerAddress|Export-Csv (Join-Path $d dns-servers.csv) -NoTypeInformation;Get-DnsClient|Export-Csv (Join-Path $d dns-clients.csv) -NoTypeInformation;Get-DnsClientCache|Select -First 1000|Export-Csv (Join-Path $d cache.csv) -NoTypeInformation;ipconfig /all|Out-File (Join-Path $d ipconfig-all.txt);foreach($n in $Names){Resolve-DnsName $n -ErrorAction Continue|Export-Csv (Join-Path $d ("resolve-{0}.csv" -f ($n -replace '[^a-zA-Z0-9.-]','_'))) -NoTypeInformation};if($DomainName){Resolve-DnsName "_ldap._tcp.dc._msdcs.$DomainName" -Type SRV -ErrorAction Continue|Export-Csv (Join-Path $d domain-dc-srv.csv) -NoTypeInformation;nltest /dsgetdc:$DomainName|Out-File (Join-Path $d domain-dc-discovery.txt)};Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-DNS-Client/Operational';StartTime=(Get-Date).AddDays(-3)} -ErrorAction SilentlyContinue|Select -First 300 TimeCreated,Id,LevelDisplayName,Message|Export-Csv (Join-Path $d dns-events.csv) -NoTypeInformation;Write-Host "DNS diagnostic bundle: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
